  "dfa": "<svg class=\"viz df\" viewBox=\"0 0 460 420\" role=\"img\" aria-label=\"A request descends through controller, service and repository; the JPA entity is stopped at the DTO boundary and a DTO returned instead, while ControllerAdvice converts exceptions to structured ApiError JSON\">\n        <use href=\"#reg\" x=\"14\" y=\"14\"></use>\n        <text class=\"t\" x=\"30\" y=\"30\">Controller → Service → Repository</text>\n        <rect class=\"ly\" x=\"96\" y=\"42\" width=\"250\" height=\"46\"></rect>\n        <text class=\"t2\" x=\"112\" y=\"70\">Controller</text>\n        <rect class=\"ly\" x=\"96\" y=\"98\" width=\"250\" height=\"46\"></rect>\n        <text class=\"t2\" x=\"112\" y=\"126\">Service</text>\n        <rect class=\"ly\" x=\"96\" y=\"154\" width=\"250\" height=\"46\"></rect>\n        <text class=\"t2\" x=\"112\" y=\"182\">Repository</text>\n        <line class=\"bd\" x1=\"96\" y1=\"94\" x2=\"346\" y2=\"94\"></line>\n        <line class=\"ax\" x1=\"88\" y1=\"94\" x2=\"96\" y2=\"94\"></line>\n        <text class=\"tg\" x=\"30\" y=\"98\">DTO /</text>\n        <text class=\"tg\" x=\"30\" y=\"112\">mapper</text>\n        <rect class=\"req\" x=\"300\" y=\"56\" width=\"15\" height=\"15\"></rect>\n        <rect class=\"ent\" x=\"300\" y=\"56\" width=\"15\" height=\"15\"></rect>\n        <rect class=\"dto\" x=\"300\" y=\"56\" width=\"15\" height=\"15\"></rect>\n        <g class=\"exX\"><path d=\"M356 106 l14 14 M370 106 l-14 14\" stroke=\"var(--hot)\" stroke-width=\"1.6\"></path></g>\n        <text class=\"th\" x=\"30\" y=\"224\">JPA entities stop at the boundary</text>\n        <text class=\"tg\" x=\"30\" y=\"240\">clients receive a DTO</text>\n        <line class=\"ax\" x1=\"30\" y1=\"258\" x2=\"430\" y2=\"258\"></line>\n        <text class=\"t\" x=\"30\" y=\"280\">@ControllerAdvice</text>\n        <rect x=\"30\" y=\"290\" width=\"172\" height=\"60\" fill=\"none\" stroke=\"var(--green-lo)\"></rect>\n        <text class=\"tg\" x=\"42\" y=\"309\">{ \"status\": 400,</text>\n        <text class=\"tg\" x=\"42\" y=\"324\">&nbsp;&nbsp;\"error\": \"...\",</text>\n        <text class=\"tg\" x=\"42\" y=\"339\">&nbsp;&nbsp;\"path\": \"/...\" }</text>\n        <text class=\"t\" x=\"216\" y=\"312\">structured ApiError JSON,</text>\n        <text class=\"t\" x=\"216\" y=\"326\">not a white-label stack trace</text>\n        <line class=\"ax\" x1=\"30\" y1=\"370\" x2=\"430\" y2=\"370\"></line>\n        <text class=\"tn\" x=\"30\" y=\"392\">7</text><text class=\"t\" x=\"44\" y=\"392\">teams</text>\n        <text class=\"tn\" x=\"110\" y=\"392\">56</text><text class=\"t\" x=\"132\" y=\"392\">members</text>\n        <text class=\"tn\" x=\"222\" y=\"392\">2</text><text class=\"t\" x=\"236\" y=\"392\">MVPs to live partners</text>\n        <text class=\"t\" x=\"30\" y=\"412\">It worked, but it taught nobody how real systems are layered.</text>\n      </svg>",
  "chicagoland": "<svg class=\"viz hf\" viewBox=\"0 0 460 420\" role=\"img\" aria-label=\"Founded December 2020 and run for three years and five months, reaching over 300 students, raising over 5,400 dollars with full donor transparency, and serving 13,000 page views in 2024\">\n        <use href=\"#reg\" x=\"14\" y=\"14\"></use>\n        <text class=\"t\" x=\"52\" y=\"30\">active span</text>\n        <g class=\"dimt\">\n          <line x1=\"52\" y1=\"70\" x2=\"408\" y2=\"70\" stroke=\"var(--amber)\" marker-start=\"url(#arA)\" marker-end=\"url(#arA)\"></line>\n          <line class=\"ax\" x1=\"52\" y1=\"64\" x2=\"52\" y2=\"76\"></line>\n          <line class=\"ax\" x1=\"408\" y1=\"64\" x2=\"408\" y2=\"76\"></line>\n          <text class=\"tn\" x=\"168\" y=\"62\">3 years, 5 months</text>\n        </g>\n        <rect x=\"52\" y=\"86\" width=\"356\" height=\"18\" fill=\"rgba(150,185,172,.08)\"></rect>\n        <rect class=\"span\" x=\"52\" y=\"86\" width=\"356\" height=\"18\" fill=\"url(#fadeAmber)\"></rect>\n        <g><line x1=\"60.6829268292683\" y1=\"86\" x2=\"60.6829268292683\" y2=\"104\" class=\"gl\"></line><line x1=\"60.6829268292683\" y1=\"104\" x2=\"60.6829268292683\" y2=\"110\" class=\"ax\"></line><text x=\"49.6829268292683\" y=\"122\" class=\"tt\">2021</text><line x1=\"164.8780487804878\" y1=\"86\" x2=\"164.8780487804878\" y2=\"104\" class=\"gl\"></line><line x1=\"164.8780487804878\" y1=\"104\" x2=\"164.8780487804878\" y2=\"110\" class=\"ax\"></line><text x=\"153.8780487804878\" y=\"122\" class=\"tt\">2022</text><line x1=\"269.0731707317073\" y1=\"86\" x2=\"269.0731707317073\" y2=\"104\" class=\"gl\"></line><line x1=\"269.0731707317073\" y1=\"104\" x2=\"269.0731707317073\" y2=\"110\" class=\"ax\"></line><text x=\"258.0731707317073\" y=\"122\" class=\"tt\">2023</text><line x1=\"373.2682926829268\" y1=\"86\" x2=\"373.2682926829268\" y2=\"104\" class=\"gl\"></line><line x1=\"373.2682926829268\" y1=\"104\" x2=\"373.2682926829268\" y2=\"110\" class=\"ax\"></line><text x=\"362.2682926829268\" y=\"122\" class=\"tt\">2024</text></g>\n        <line class=\"ax\" x1=\"52\" y1=\"86\" x2=\"52\" y2=\"104\"></line>\n        <line class=\"ax\" x1=\"408\" y1=\"86\" x2=\"408\" y2=\"104\"></line>\n        <text class=\"t\" x=\"52\" y=\"140\">Dec 2020</text>\n        <text class=\"t\" x=\"366\" y=\"140\">May 2024</text>\n        <text class=\"t\" x=\"52\" y=\"160\">founded during the pandemic, run while enrolled full-time</text>\n        <g class=\"ms\" style=\"--d:1.9s\">\n          <path d=\"M350 174 L 350 182 L 408 182 L 408 174\" fill=\"none\" stroke=\"var(--green-hi)\"></path>\n          <text class=\"tg\" x=\"266\" y=\"196\">13,000 page views in 2024</text>\n        </g>\n        <line class=\"ax\" x1=\"30\" y1=\"220\" x2=\"430\" y2=\"220\"></line>\n        <text class=\"tbig\" x=\"30\" y=\"256\">$5,400+</text>\n        <text class=\"t\" x=\"30\" y=\"274\">raised · 100% donor transparency</text>\n        <line class=\"ax\" x1=\"240\" y1=\"230\" x2=\"240\" y2=\"280\"></line>\n        <text class=\"tn\" x=\"262\" y=\"250\">300+</text>\n        <text class=\"t\" x=\"262\" y=\"266\">under-served students</text>\n        <text class=\"t\" x=\"262\" y=\"280\">in the Chicago area</text>\n        <line class=\"ax\" x1=\"30\" y1=\"304\" x2=\"430\" y2=\"304\"></line>\n        <text class=\"t\" x=\"30\" y=\"326\">React and Node.js · continuous releases shipped through a</text>\n        <text class=\"t\" x=\"30\" y=\"340\">GitHub Actions CI/CD pipeline</text>\n        <text class=\"t2\" x=\"30\" y=\"382\">The longest-running thing I have built, and the only</text>\n        <text class=\"t2\" x=\"30\" y=\"397\">one where I was accountable for the money.</text>\n      </svg>",
